// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(uint16 _feeRate) public {
        // Admissible fee rates: the full uint16 range.
        // The reference allows only <=5000; the mutant allows only >5000.
        // We attempt initialize and check whether it succeeded, then read the stored feeRate.
        bool referenceSuccess;
        uint16 storedFee;

        // Phase 1: drive initialize on a FRESH instance (since initialized=true prevents re-init).
        {
            C fresh = new C(address(this), address(this), address(this));
            try fresh.initialize(
                address(0x1),
                address(0x2),
                100,
                200,
                0,
                _feeRate,
                bytes32(0),
                false,
                false
            ) {
                referenceSuccess = true;
                storedFee = fresh.feeRate();
            } catch {
                referenceSuccess = false;
            }
        }

        if (referenceSuccess) {
            // If initialize succeeded, the stored feeRate must be <= 5000.
            // In the reference this always holds. In the mutant, a feeRate > 5000 succeeds
            // and storedFee will be > 5000, breaking the assertion.
            assertTrue(storedFee <= 5000);
        }
        // If initialize reverted, the invariant vacuously holds (no feeRate stored).
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        vm.assume(_feeRate <= 5000);
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );
        assertTrue(c.feeRate() == _feeRate);
    }
}
